import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { list_all_cargo_items } from "@/graphql/queries.js";
import EditItemDialog from "./PopUpsDialogues/EditItemDialog.vue";
import DeleteItemDialog from "./PopUpsDialogues/DeleteItemDialog.vue";
export default {
  components: {
    SnackBar,
    EditItemDialog,
    DeleteItemDialog
  },
  data() {
    return {
      componentCheck: 0,
      search: "",
      searchlist: "",
      tableLoading: false,
      SnackBarComponent: {},
      tableData: [],
      ListHeaders: [{
        text: "Name",
        value: "cargo_item_name",
        sortable: false
      }, {
        text: "Length(mts)",
        value: "length_in_mts",
        sortable: false
      }, {
        text: "Width(mts)",
        value: "width_in_mts",
        sortable: false
      }, {
        text: "Height(mts)",
        value: "height_in_mts",
        sortable: false
      }, {
        text: "Load(lb)",
        value: "max_load_in_lb",
        sortable: false
      }, {
        text: "Action",
        value: "actions",
        sortable: false
      }],
      editItemDialog: false,
      rowInfo: {},
      deleteItemDialog: false
    };
  },
  async mounted() {
    await this.fetch_cargo_list();
  },
  methods: {
    edit_item(item) {
      this.componentCheck = 1;
      this.editItemDialog = true;
      this.rowInfo = item;
    },
    delete_item(item) {
      this.componentCheck = 2;
      this.deleteItemDialog = true;
      this.rowInfo = item;
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.deleteItemDialog = false;
      this.editItemDialog = false;
      await this.fetch_cargo_list();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_cargo_list() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_all_cargo_items, {
          input: {}
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.list_all_cargo_items);
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
